import base64,io,json,subprocess,sys,tarfile
from pathlib import Path
root=Path("/tmp/moe-compiled-g4-20261112")
root.mkdir(exist_ok=True)
assert not (root/"launch.json").exists(),"Do not launch duplicate workers"
(root/'worker.py').write_bytes(base64.b64decode(''))
(root/'source-manifest.json').write_bytes(base64.b64decode(''))
(root/'expected-inputs.json').write_bytes(base64.b64decode(''))
source=root/"source"
source.mkdir(exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode="r:gz") as tar:
 tar.extractall(source,filter="data")
with (root/"worker.stdout").open("w") as stdout,(root/"worker.stderr").open("w") as stderr:
 p=subprocess.Popen([sys.executable,"-u",str(root/"worker.py")],stdout=stdout,stderr=stderr,start_new_session=True)
(root/"launch.json").write_text(json.dumps({"pid":p.pid}))
print(json.dumps({"pid":p.pid}))
